CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "Categorias" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UsuarioId" uuid,
    "Nombre" text NOT NULL,
    "Icono" text NOT NULL,
    "ColorHex" text NOT NULL,
    "Tipo" text NOT NULL,
    "Activa" boolean NOT NULL,
    CONSTRAINT "PK_Categorias" PRIMARY KEY ("Id")
);

CREATE TABLE "PagosRecurrentes" (
    "Id" uuid NOT NULL,
    "UsuarioId" uuid NOT NULL,
    "Concepto" text NOT NULL,
    "Monto" numeric NOT NULL,
    "DiaDelMes" integer NOT NULL,
    "CategoriaId" integer NOT NULL,
    "Activo" boolean NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_PagosRecurrentes" PRIMARY KEY ("Id")
);

CREATE TABLE "PresupuestosMensuales" (
    "Id" uuid NOT NULL,
    "UsuarioId" uuid NOT NULL,
    "Mes" integer NOT NULL,
    "Anio" integer NOT NULL,
    "IngresoEstimado" numeric NOT NULL,
    "MetaAhorro" numeric NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_PresupuestosMensuales" PRIMARY KEY ("Id")
);

CREATE TABLE "Transacciones" (
    "Id" uuid NOT NULL,
    "UsuarioId" uuid NOT NULL,
    "Monto" numeric NOT NULL,
    "Descripcion" text NOT NULL,
    "Fecha" timestamp with time zone NOT NULL,
    "Tipo" text NOT NULL,
    "CategoriaId" integer NOT NULL,
    "EsGastoFijo" boolean NOT NULL,
    "IsDeleted" boolean NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Transacciones" PRIMARY KEY ("Id")
);

CREATE TABLE "Usuarios" (
    "Id" uuid NOT NULL,
    "Email" text NOT NULL,
    "PasswordHash" text NOT NULL,
    "Nombre" text NOT NULL,
    "FechaCreacion" timestamp with time zone NOT NULL,
    "UltimoLogin" timestamp with time zone,
    CONSTRAINT "PK_Usuarios" PRIMARY KEY ("Id")
);

